-- aether
INSERT INTO works (brand_id, slug, sort_order, status, published_at, cover_asset_id,
  title, tagline, role, services, overview, highlights, body, meta)
VALUES (
  (SELECT id FROM brands WHERE slug='werkero'),
  'aether',
  4,
  'published',
  now(),
  NULL,
  '{"en": "Aether", "zh-cn": "Aether", "zh-tw": "Aether", "fr": "Aether", "de": "Aether", "ru": "Aether", "ja": "Aether"}',
  '{"en": "AI-powered inspiration capture and execution.", "zh-cn": "AI 驱动的灵感捕捉与执行。", "zh-tw": "AI 驅動的靈感捕捉與執行。", "fr": "Capture d''inspiration et exécution propulsées par l''IA.", "de": "KI-gestütztes Festhalten und Umsetzen von Inspiration.", "ru": "ИИ-захват вдохновения и его исполнение.", "ja": "AIによるひらめきの捕捉と実行。"}',
  '{"en": "Product design & engineering", "zh-cn": "产品设计与工程", "zh-tw": "產品設計與工程", "fr": "Design produit & ingénierie", "de": "Produktdesign & Engineering", "ru": "Дизайн продукта и инженерия", "ja": "プロダクトデザイン＆エンジニアリング"}',
  '{"en": ["Product design", "Web app", "AI integration"], "zh-cn": ["产品设计", "网站应用", "AI 集成"], "zh-tw": ["產品設計", "網站應用", "AI 整合"], "fr": ["Design produit", "Application web", "Intégration IA"], "de": ["Produktdesign", "Web-App", "KI-Integration"], "ru": ["Дизайн продукта", "Веб-приложение", "ИИ-интеграция"], "ja": ["プロダクトデザイン", "Webアプリ", "AIインテグレーション"]}',
  '{"en": "Aether captures fleeting inspiration with AI and turns it into executable next steps.", "zh-cn": "Aether 用 AI 捕捉稍纵即逝的灵感，并把它变成可执行的下一步。", "zh-tw": "Aether 用 AI 捕捉稍縱即逝的靈感，並把它變成可執行的下一步。", "fr": "Aether capture l''inspiration fugace grâce à l''IA et la transforme en prochaines étapes exécutables.", "de": "Aether hält flüchtige Inspiration mit KI fest und macht daraus umsetzbare nächste Schritte.", "ru": "Aether ловит мимолётное вдохновение с помощью ИИ и превращает его в исполнимые следующие шаги.", "ja": "Aether はAIで儚いひらめきを捉え、実行可能な次のステップに変える。"}',
  '{"en": ["Frictionless capture, anywhere", "AI turns notes into action plans", "Glassmorphism interface"], "zh-cn": ["随时随地，无摩擦捕捉", "AI 把笔记变成行动计划", "玻璃拟态界面"], "zh-tw": ["隨時隨地，無摩擦捕捉", "AI 把筆記變成行動計畫", "玻璃擬態介面"], "fr": ["Capture sans friction, partout", "L''IA transforme les notes en plans d''action", "Interface en glassmorphism"], "de": ["Reibungsloses Capturing, überall", "KI macht aus Notizen Aktionspläne", "Glassmorphism-Interface"], "ru": ["Захват без трения, где угодно", "ИИ превращает заметки в планы действий", "Glassmorphism-интерфейс"], "ja": ["どこでも、摩擦のないキャプチャ", "AIがメモを実行計画に変換", "グラスモーフィズムのインターフェース"]}',
  '{"en": "Ideas die in inboxes. Aether treats every captured thought as the start of a workflow — the AI reads intent, proposes structure, and hands back something you can act on.\n\nBuilt for people whose best thinking happens away from the desk.", "zh-cn": "灵感死在收件箱里。Aether 把每个捕捉到的想法都当作工作流的起点——AI 读懂意图、给出结构，交还给你可以行动的东西。\n\n为那些最好的思考发生在办公桌之外的人而造。", "zh-tw": "靈感死在收件匣裡。Aether 把每個捕捉到的想法都當作工作流的起點——AI 讀懂意圖、給出結構，交還給你可以行動的東西。\n\n為那些最好的思考發生在辦公桌之外的人而造。", "fr": "Les idées meurent dans les boîtes de réception. Aether traite chaque pensée capturée comme le début d''un workflow — l''IA lit l''intention, propose une structure et rend quelque chose d''actionnable.\n\nConçu pour ceux dont les meilleures idées naissent loin du bureau.", "de": "Ideen sterben in Postfächern. Aether behandelt jeden festgehaltenen Gedanken als Workflow-Start — die KI liest die Intention, schlägt Struktur vor und gibt etwas Handlungsfähiges zurück.\n\nGebaut für alle, deren bestes Denken abseits des Schreibtischs passiert.", "ru": "Идеи умирают во входящих. Aether относится к каждой пойманной мысли как к началу workflow — ИИ считывает намерение, предлагает структуру и возвращает то, с чем можно действовать.\n\nСоздан для тех, чьи лучшие мысли приходят вне офиса.", "ja": "アイデアは受信箱で死ぬ。Aether は捉えた思考のすべてをワークフローの起点として扱う——AIが意図を読み取り、構造を提案し、行動できるものを返す。\n\n最高の思考がデスクの外で生まれる人のために。"}',
  '{"en": {"title": "Aether", "description": "AI-powered inspiration capture and execution."}, "zh-cn": {"title": "Aether", "description": "AI 驱动的灵感捕捉与执行。"}, "zh-tw": {"title": "Aether", "description": "AI 驅動的靈感捕捉與執行。"}, "fr": {"title": "Aether", "description": "Capture d''inspiration et exécution propulsées par l''IA."}, "de": {"title": "Aether", "description": "KI-gestütztes Festhalten und Umsetzen von Inspiration."}, "ru": {"title": "Aether", "description": "ИИ-захват вдохновения и его исполнение."}, "ja": {"title": "Aether", "description": "AIによるひらめきの捕捉と実行。"}}'
);

-- ai-archives
INSERT INTO works (brand_id, slug, sort_order, status, published_at, cover_asset_id,
  title, tagline, role, services, overview, highlights, body, meta)
VALUES (
  (SELECT id FROM brands WHERE slug='werkero'),
  'ai-archives',
  2,
  'published',
  now(),
  NULL,
  '{"en": "AI Archives", "zh-cn": "AI 机要室", "zh-tw": "AI 機要室", "fr": "AI Archives", "de": "AI Archives", "ru": "AI Archives", "ja": "AI Archives"}',
  '{"en": "An archive of AI history and AI news.", "zh-cn": "AI 历史与 AI 新闻的档案馆。", "zh-tw": "AI 歷史與 AI 新聞的檔案館。", "fr": "Une archive de l''histoire de l''IA et de son actualité.", "de": "Ein Archiv für KI-Geschichte und KI-News.", "ru": "Архив истории ИИ и новостей ИИ.", "ja": "AIの歴史とAIニュースのアーカイブ。"}',
  '{"en": "Concept, design & engineering", "zh-cn": "概念、设计与工程", "zh-tw": "概念、設計與工程", "fr": "Concept, design & ingénierie", "de": "Konzept, Design & Engineering", "ru": "Концепция, дизайн и инженерия", "ja": "コンセプト・デザイン＆エンジニアリング"}',
  '{"en": ["Editorial design", "Web app"], "zh-cn": ["编辑设计", "网站应用"], "zh-tw": ["編輯設計", "網站應用"], "fr": ["Design éditorial", "Application web"], "de": ["Editorial Design", "Web-App"], "ru": ["Редакционный дизайн", "Веб-приложение"], "ja": ["エディトリアルデザイン", "Webアプリ"]}',
  '{"en": "AI Archives (AI 机要室) is a living archive documenting the history of artificial intelligence alongside its daily news.", "zh-cn": "AI 机要室是一座活的档案馆，记录人工智能的历史，也记录它每天的新闻。", "zh-tw": "AI 機要室是一座活的檔案館，記錄人工智慧的歷史，也記錄它每天的新聞。", "fr": "AI Archives (AI 机要室) est une archive vivante qui documente l''histoire de l''intelligence artificielle ainsi que son actualité quotidienne.", "de": "AI Archives (AI 机要室) ist ein lebendiges Archiv, das die Geschichte der künstlichen Intelligenz und ihre täglichen News dokumentiert.", "ru": "AI Archives (AI 机要室) — живой архив, документирующий историю искусственного интеллекта и его ежедневные новости.", "ja": "AI Archives（AI 机要室）は、人工知能の歴史と日々のニュースを記録する生きたアーカイブ。"}',
  '{"en": ["Covers both AI history and AI news", "Archive-grade editorial presentation", "Fully multilingual reading experience"], "zh-cn": ["兼顾 AI 历史与 AI 新闻", "档案级的编辑呈现", "全多语言阅读体验"], "zh-tw": ["兼顧 AI 歷史與 AI 新聞", "檔案級的編輯呈現", "全多語言閱讀體驗"], "fr": ["Couvre l''histoire et l''actualité de l''IA", "Présentation éditoriale digne d''une archive", "Expérience de lecture entièrement multilingue"], "de": ["Deckt KI-Geschichte und KI-News ab", "Editoriale Präsentation auf Archiv-Niveau", "Vollständig mehrsprachiges Leseerlebnis"], "ru": ["Охватывает историю и новости ИИ", "Редакционная подача архивного уровня", "Полностью мультиязычный опыт чтения"], "ja": ["AIの歴史とニュースの両方をカバー", "アーカイブ級の編集プレゼンテーション", "完全多言語の読書体験"]}',
  '{"en": "The project treats AI''s story with the seriousness of an archive: every era documented, every development filed. History gives the news context; the news keeps the history alive.\n\nIt is designed to be read slowly — a counterweight to the feed-speed coverage of the field.", "zh-cn": "这个项目以档案的严肃对待 AI 的故事：每个时代都被记录，每个进展都被归档。历史给新闻以语境，新闻让历史保持鲜活。\n\n它是为慢阅读设计的——对抗信息流速度的配速。", "zh-tw": "這個專案以檔案的嚴肅對待 AI 的故事：每個時代都被記錄，每個進展都被歸檔。歷史給新聞以語境，新聞讓歷史保持鮮活。\n\n它是為慢閱讀設計的——對抗資訊流速度的配速。", "fr": "Le projet traite l''histoire de l''IA avec le sérieux d''une archive : chaque époque documentée, chaque avancée classée. L''histoire donne un contexte à l''actualité ; l''actualité garde l''histoire vivante.\n\nConçu pour une lecture lente — un contrepoids à la couverture à la vitesse du flux.", "de": "Das Projekt behandelt die Geschichte der KI mit der Ernsthaftigkeit eines Archivs: jede Ära dokumentiert, jeder Fortschritt abgelegt. Geschichte gibt den News Kontext; News halten die Geschichte lebendig.\n\nFür langsames Lesen gebaut — ein Gegengewicht zur Feed-Geschwindigkeit.", "ru": "Проект относится к истории ИИ с серьёзностью архива: каждая эпоха задокументирована, каждое достижение подшито. История даёт новостям контекст; новости поддерживают историю живой.\n\nСоздан для медленного чтения — противовес скорости ленты.", "ja": "このプロジェクトはAIの物語をアーカイブの真剣さで扱う：すべての時代を記録し、すべての進展をファイリング。歴史がニュースに文脈を与え、ニュースが歴史を生かし続ける。\n\nスローリーディングのために設計——フィード速度の報道への対抗軸。"}',
  '{"en": {"title": "AI Archives", "description": "An archive of AI history and AI news."}, "zh-cn": {"title": "AI 机要室", "description": "AI 历史与 AI 新闻的档案馆。"}, "zh-tw": {"title": "AI 機要室", "description": "AI 歷史與 AI 新聞的檔案館。"}, "fr": {"title": "AI Archives", "description": "Une archive de l''histoire de l''IA et de son actualité."}, "de": {"title": "AI Archives", "description": "Ein Archiv für KI-Geschichte und KI-News."}, "ru": {"title": "AI Archives", "description": "Архив истории ИИ и новостей ИИ."}, "ja": {"title": "AI Archives", "description": "AIの歴史とAIニュースのアーカイブ。"}}'
);

