INSERT INTO works (brand_id, slug, sort_order, status, published_at, cover_asset_id,
  title, tagline, role, services, overview, highlights, body, meta)
VALUES (
  (SELECT id FROM brands WHERE slug='werkero'),
  'arkhyx-blog',
  5,
  'published',
  now(),
  NULL,
  '{"en": "Arkhyx Blog", "zh-cn": "Arkhyx Blog", "zh-tw": "Arkhyx Blog", "fr": "Arkhyx Blog", "de": "Arkhyx Blog", "ru": "Arkhyx Blog", "ja": "Arkhyx Blog"}',
  '{"en": "An open-source blog project.", "zh-cn": "一个开源博客项目。", "zh-tw": "一個開源部落格專案。", "fr": "Un projet de blog open-source.", "de": "Ein Open-Source-Blogprojekt.", "ru": "Блог-проект с открытым исходным кодом.", "ja": "オープンソースのブログプロジェクト。"}',
  '{"en": "Design & engineering", "zh-cn": "设计与工程", "zh-tw": "設計與工程", "fr": "Design & ingénierie", "de": "Design & Engineering", "ru": "Дизайн и инженерия", "ja": "デザイン＆エンジニアリング"}',
  '{"en": ["Open source", "Web app"], "zh-cn": ["开源", "网站应用"], "zh-tw": ["開源", "網站應用"], "fr": ["Open source", "Application web"], "de": ["Open Source", "Web-App"], "ru": ["Открытый код", "Веб-приложение"], "ja": ["オープンソース", "Webアプリ"]}',
  '{"en": "Arkhyx Blog is an open-source blog project — a clean, fast publishing setup anyone can run.", "zh-cn": "Arkhyx Blog 是一个开源博客项目——干净、快速，任何人都能跑起来。", "zh-tw": "Arkhyx Blog 是一個開源部落格專案——乾淨、快速，任何人都能跑起來。", "fr": "Arkhyx Blog est un projet de blog open-source — une configuration de publication propre et rapide, que chacun peut héberger.", "de": "Arkhyx Blog ist ein Open-Source-Blogprojekt — ein sauberes, schnelles Publishing-Setup für alle.", "ru": "Arkhyx Blog — блог-проект с открытым кодом: чистая и быстрая издательская платформа, которую может запустить каждый.", "ja": "Arkhyx Blog はオープンソースのブログプロジェクト——クリーンで高速、誰でも運用できるパブリッシング環境。"}',
  '{"en": ["Open-source and self-hostable", "Minimal, reading-first design", "Built as a public learning artifact"], "zh-cn": ["开源，可自行托管", "极简，以阅读为先的设计", "作为公开的学习记录构建"], "zh-tw": ["開源，可自行託管", "極簡，以閱讀為先的設計", "作為公開的學習紀錄構建"], "fr": ["Open-source et auto-hébergeable", "Design minimal, priorité à la lecture", "Construit comme un artefact public d''apprentissage"], "de": ["Open-Source und selbst hostbar", "Minimal, lesen zuerst", "Als öffentliches Lern-Artefakt gebaut"], "ru": ["Открытый код, можно хостить самому", "Минимализм, чтение на первом месте", "Построен как публичный учебный материал"], "ja": ["オープンソース、セルフホスト可能", "ミニマル、読書ファーストのデザイン", "公開学習の記録として構築"]}',
  '{"en": "Some projects are for shipping; this one is for sharing. Arkhyx Blog is built in the open so the decisions, mistakes, and trade-offs are all visible.\n\nA reminder that the studio''s craft improves when the process is public.", "zh-cn": "有些项目为交付，这个为分享。Arkhyx Blog 在开放中构建，决策、错误和权衡全部可见。\n\n提醒工作室：过程公开时，手艺才会更好。", "zh-tw": "有些專案為交付，這個為分享。Arkhyx Blog 在開放中構建，決策、錯誤和權衡全部可見。\n\n提醒工作室：過程公開時，手藝才會更好。", "fr": "Certains projets sont faits pour livrer ; celui-ci est fait pour partager. Arkhyx Blog est construit en public : décisions, erreurs et arbitrages sont visibles.\n\nUn rappel que le craft du studio s''améliore quand le processus est public.", "de": "Manche Projekte sind zum Shippedwerden da; dieses zum Teilen. Arkhyx Blog entsteht in der Öffentlichkeit — Entscheidungen, Fehler und Trade-offs sind sichtbar.\n\nEine Erinnerung: Das Craft des Studios wächst, wenn der Prozess öffentlich ist.", "ru": "Некоторые проекты создаются ради релиза; этот — ради того, чтобы делиться. Arkhyx Blog строится открыто: решения, ошибки и компромиссы видны всем.\n\nНапоминание: мастерство студии растёт, когда процесс публичен.", "ja": "届けるためのプロジェクトもあれば、分かち合うためのプロジェクトもある。Arkhyx Blog はオープンに構築される——判断も失敗もトレードオフも見える。\n\nスタジオの技芸は、プロセスが公開されるときに磨かれる、というリマインダー。"}',
  '{"en": {"title": "Arkhyx Blog", "description": "An open-source blog project."}, "zh-cn": {"title": "Arkhyx Blog", "description": "一个开源博客项目。"}, "zh-tw": {"title": "Arkhyx Blog", "description": "一個開源部落格專案。"}, "fr": {"title": "Arkhyx Blog", "description": "Un projet de blog open-source."}, "de": {"title": "Arkhyx Blog", "description": "Ein Open-Source-Blogprojekt."}, "ru": {"title": "Arkhyx Blog", "description": "Блог-проект с открытым исходным кодом."}, "ja": {"title": "Arkhyx Blog", "description": "オープンソースのブログプロジェクト。"}}'
);

