  'awarely',
  3,
  'published',
  now(),
  NULL,
  '{"en": "Awarely", "zh-cn": "Awarely", "zh-tw": "Awarely", "fr": "Awarely", "de": "Awarely", "ru": "Awarely", "ja": "Awarely"}',
  '{"en": "Cross-border e-commerce brand, growing into AI home decision-making.", "zh-cn": "跨境电商品牌，正在走向 AI 居家决策。", "zh-tw": "跨境電商品牌，正在走向 AI 居家決策。", "fr": "Marque e-commerce transfrontalière, en route vers la décision IA à la maison.", "de": "Cross-Border-E-Commerce-Marke, auf dem Weg zur KI-Haushaltsentscheidung.", "ru": "Трансграничный e-commerce бренд на пути к ИИ-решениям для дома.", "ja": "越境ECブランド、AIホーム意思決定へ。"}',
  '{"en": "Brand & product engineering", "zh-cn": "品牌与产品工程", "zh-tw": "品牌與產品工程", "fr": "Marque & ingénierie produit", "de": "Brand & Product Engineering", "ru": "Бренд и продуктовая инженерия", "ja": "ブランド＆プロダクトエンジニアリング"}',
  '{"en": ["Brand identity", "E-commerce", "AI product"], "zh-cn": ["品牌识别", "电商", "AI 产品"], "zh-tw": ["品牌識別", "電商", "AI 產品"], "fr": ["Identité de marque", "E-commerce", "Produit IA"], "de": ["Markenidentität", "E-Commerce", "KI-Produkt"], "ru": ["Айдентика бренда", "E-commerce", "ИИ-продукт"], "ja": ["ブランドアイデンティティ", "EC", "AIプロダクト"]}',
  '{"en": "Awarely began as a cross-border e-commerce brand and is growing toward AI-assisted home decisions and family health companionship.", "zh-cn": "Awarely 起步于跨境电商，正在走向 AI 辅助的居家决策与家庭健康陪伴。", "zh-tw": "Awarely 起步於跨境電商，正在走向 AI 輔助的居家決策與家庭健康陪伴。", "fr": "Awarely a commencé comme marque e-commerce transfrontalière et évolue vers l''aide à la décision domestique par IA et l''accompagnement santé familial.", "de": "Awarely startete als Cross-Border-E-Commerce-Marke und wächst in Richtung KI-gestützter Haushaltsentscheidungen und familiärer Gesundheitsbegleitung.", "ru": "Awarely начинался как трансграничный e-commerce бренд и движется в сторону ИИ-помощи в домашних решениях и сопровождения семейного здоровья.", "ja": "Awarely は越境ECブランドとして始まり、AIによる家庭の意思決定支援とファミリーヘルスの同伴へ向かっている。"}',
  '{"en": ["Cross-border retail brand and storefront", "Expanding into AI home decision support", "Family health companion direction"], "zh-cn": ["跨境零售品牌与店面", "正在拓展 AI 居家决策支持", "家庭健康陪伴方向"], "zh-tw": ["跨境零售品牌與店面", "正在拓展 AI 居家決策支援", "家庭健康陪伴方向"], "fr": ["Marque retail transfrontalière et boutique", "Expansion vers l''aide à la décision domestique par IA", "Direction compagnon santé familial"], "de": ["Cross-Border-Retail-Marke und Storefront", "Ausbau Richtung KI-Haushaltsentscheidungen", "Familiäre Gesundheitsbegleitung als Richtung"], "ru": ["Трансграничный ритейл-бренд и витрина", "Расширение в ИИ-поддержку домашних решений", "Направление — компаньон для семейного здоровья"], "ja": ["越境リテールブランドとストア", "AI家庭意思決定支援への拡張", "ファミリーヘルス同伴という方向性"]}',
  '{"en": "Awarely proves a brand can start in commerce and earn its way into people''s homes. The retail operation funds the longer bet: an AI companion for household decisions and health.\n\nOne brand, two horizons — selling today, caring tomorrow.", "zh-cn": "Awarely 证明一个品牌可以从商业起步，一路走进人们的家。零售业务为更长远的赌注提供资金：为家庭决策和健康服务的 AI 陪伴。\n\n一个品牌，两个地平线——今天做生意，明天做陪伴。", "zh-tw": "Awarely 證明一個品牌可以從商業起步，一路走進人們的家。零售業務為更長遠的賭注提供資金：為家庭決策和健康服務的 AI 陪伴。\n\n一個品牌，兩個地平線——今天做生意，明天做陪伴。", "fr": "Awarely prouve qu''une marque peut naître dans le commerce et se frayer un chemin jusqu''aux foyers. L''activité retail finance le pari long : un compagnon IA pour les décisions du foyer et la santé.\n\nUne marque, deux horizons — vendre aujourd''hui, prendre soin demain.", "de": "Awarely beweist: Eine Marke kann im Handel starten und sich bis in die Wohnzimmer vorarbeiten. Das Retail-Geschäft finanziert die lange Wette: ein KI-Begleiter für Haushaltsentscheidungen und Gesundheit.\n\nEine Marke, zwei Horizonte — heute verkaufen, morgen begleiten.", "ru": "Awarely доказывает: бренд может родиться в коммерции и дойти до гостиных. Ритейл финансирует долгую ставку — ИИ-компаньона для домашних решений и здоровья.\n\nОдин бренд, два горизонта — сегодня продавать, завтра заботиться.", "ja": "Awarely は証明する：ブランドはコマースから生まれ、家庭のリビングまでたどり着ける。リテール事業が長期の賭けを支える——家庭の意思決定と健康のためのAIコンパニオン。\n\n一つのブランド、二つの地平線——今日は売り、明日は寄り添う。"}',
  '{"en": {"title": "Awarely", "description": "Cross-border e-commerce brand, growing into AI home decision-making."}, "zh-cn": {"title": "Awarely", "description": "跨境电商品牌，正在走向 AI 居家决策。"}, "zh-tw": {"title": "Awarely", "description": "跨境電商品牌，正在走向 AI 居家決策。"}, "fr": {"title": "Awarely", "description": "Marque e-commerce transfrontalière, en route vers la décision IA à la maison."}, "de": {"title": "Awarely", "description": "Cross-Border-E-Commerce-Marke, auf dem Weg zur KI-Haushaltsentscheidung."}, "ru": {"title": "Awarely", "description": "Трансграничный e-commerce бренд на пути к ИИ-решениям для дома."}, "ja": {"title": "Awarely", "description": "越境ECブランド、AIホーム意思決定へ。"}}'
);

