INSERT INTO works (brand_id, slug, sort_order, status, published_at, cover_asset_id,
  title, tagline, role, services, overview, highlights, body, meta)
VALUES (
  (SELECT id FROM brands WHERE slug='werkero'),
  'kyvero',
  6,
  'published',
  now(),
  NULL,
  '{"en": "Kyvero", "zh-cn": "Kyvero", "zh-tw": "Kyvero", "fr": "Kyvero", "de": "Kyvero", "ru": "Kyvero", "ja": "Kyvero"}',
  '{"en": "A sibling project in the -ero brand family.", "zh-cn": "-ero 品牌家族的兄弟项目。", "zh-tw": "-ero 品牌家族的兄弟專案。", "fr": "Un projet frère dans la famille de marques -ero.", "de": "Ein Schwesterprojekt in der -ero-Markenfamilie.", "ru": "Родственный проект в бренд-семье -ero.", "ja": "-eroブランドファミリーの兄弟プロジェクト。"}',
  '{"en": "Brand & engineering", "zh-cn": "品牌与工程", "zh-tw": "品牌與工程", "fr": "Marque & ingénierie", "de": "Brand & Engineering", "ru": "Бренд и инженерия", "ja": "ブランド＆エンジニアリング"}',
  '{"en": ["Brand system", "Web app"], "zh-cn": ["品牌体系", "网站应用"], "zh-tw": ["品牌體系", "網站應用"], "fr": ["Système de marque", "Application web"], "de": ["Markensystem", "Web-App"], "ru": ["Система бренда", "Веб-приложение"], "ja": ["ブランドシステム", "Webアプリ"]}',
  '{"en": "Kyvero is a sibling project in the -ero brand family — sharing the studio''s design language and engineering standards.", "zh-cn": "Kyvero 是 -ero 品牌家族的兄弟项目——共享工作室的设计语言与工程标准。", "zh-tw": "Kyvero 是 -ero 品牌家族的兄弟專案——共享工作室的設計語言與工程標準。", "fr": "Kyvero est un projet frère dans la famille de marques -ero — il partage le langage design et les standards d''ingénierie du studio.", "de": "Kyvero ist ein Schwesterprojekt in der -ero-Markenfamilie — es teilt Designsprache und Engineering-Standards des Studios.", "ru": "Kyvero — родственный проект в бренд-семье -ero: разделяет дизайн-язык и инженерные стандарты студии.", "ja": "Kyvero は-eroブランドファミリーの兄弟プロジェクト——スタジオのデザイン言語とエンジニアリング基準を共有する。"}',
  '{"en": ["Part of the Kyvero · Laurero · Werkero family", "Shared design DNA across projects", "Independent product, shared craft"], "zh-cn": ["Kyvero · Laurero · Werkero 家族一员", "项目间共享设计 DNA", "独立产品，共享手艺"], "zh-tw": ["Kyvero · Laurero · Werkero 家族一員", "專案間共享設計 DNA", "獨立產品，共享手藝"], "fr": ["Membre de la famille Kyvero · Laurero · Werkero", "ADN design partagé entre projets", "Produit indépendant, craft partagé"], "de": ["Teil der Familie Kyvero · Laurero · Werkero", "Geteilte Design-DNA über Projekte hinweg", "Unabhängiges Produkt, geteiltes Craft"], "ru": ["Член семьи Kyvero · Laurero · Werkero", "Общий дизайн-ДНК между проектами", "Независимый продукт, общее мастерство"], "ja": ["Kyvero · Laurero · Werkero ファミリーの一員", "プロジェクト間で共有されるデザインDNA", "独立したプロダクト、共有される技芸"]}',
  '{"en": "Kyvero, Laurero, Werkero — the family shares a suffix and a standard. Each project stands alone, but all of them carry the same care in design and engineering.\n\nThe -ero projects are the studio''s long-term compound interest.", "zh-cn": "Kyvero、Laurero、Werkero——家族共享一个后缀和一套标准。每个项目独立成立，但都带着同样的设计与工程用心。\n\n-ero 项目是工作室的长期复利。", "zh-tw": "Kyvero、Laurero、Werkero——家族共享一個後綴和一套標準。每個專案獨立成立，但都帶著同樣的設計與工程用心。\n\n-ero 專案是工作室的長期複利。", "fr": "Kyvero, Laurero, Werkero — la famille partage un suffixe et un standard. Chaque projet existe seul, mais tous portent le même soin.\n\nLes projets -ero sont les intérêts composés du studio.", "de": "Kyvero, Laurero, Werkero — die Familie teilt ein Suffix und einen Standard. Jedes Projekt steht für sich, aber alle tragen dieselbe Sorgfalt.\n\nDie -ero-Projekte sind der Zinseszins des Studios.", "ru": "Kyvero, Laurero, Werkero — семья разделяет суффикс и стандарт. Каждый проект самостоятелен, но все несут одинаковую заботу.\n\nПроекты -ero — сложный процент студии.", "ja": "Kyvero、Laurero、Werkero——ファミリーは接尾辞と基準を共有する。各プロジェクトは独立しながら、同じ丁寧さを持つ。\n\n-eroプロジェクトはスタジオの長期複利。"}',
  '{"en": {"title": "Kyvero", "description": "A sibling project in the -ero brand family."}, "zh-cn": {"title": "Kyvero", "description": "-ero 品牌家族的兄弟项目。"}, "zh-tw": {"title": "Kyvero", "description": "-ero 品牌家族的兄弟專案。"}, "fr": {"title": "Kyvero", "description": "Un projet frère dans la famille de marques -ero."}, "de": {"title": "Kyvero", "description": "Ein Schwesterprojekt in der -ero-Markenfamilie."}, "ru": {"title": "Kyvero", "description": "Родственный проект в бренд-семье -ero."}, "ja": {"title": "Kyvero", "description": "-eroブランドファミリーの兄弟プロジェクト。"}}'
);

-- laurero
INSERT INTO works (brand_id, slug, sort_order, status, published_at, cover_asset_id,
  title, tagline, role, services, overview, highlights, body, meta)
VALUES (
  (SELECT id FROM brands WHERE slug='werkero'),
  'laurero',
  1,
  'published',
  now(),
  NULL,
  '{"en": "Laurero", "zh-cn": "Laurero", "zh-tw": "Laurero", "fr": "Laurero", "de": "Laurero", "ru": "Laurero", "ja": "Laurero"}',
  '{"en": "AI gaokao application advisor that dares to tell the truth.", "zh-cn": "敢说真话的 AI 高考志愿填报顾问。", "zh-tw": "敢說真話的 AI 高考志願填報顧問。", "fr": "Conseiller IA d''orientation gaokao qui ose dire la vérité.", "de": "KI-Berater für die Gaokao-Bewerbung, der die Wahrheit sagt.", "ru": "ИИ-консультант по gaokao, который не боится говорить правду.", "ja": "真実を語ることを恐れないAI高考志願アドバイザー。"}',
  '{"en": "Product design & engineering", "zh-cn": "产品设计与工程", "zh-tw": "產品設計與工程", "fr": "Design produit & ingénierie", "de": "Produktdesign & Engineering", "ru": "Дизайн продукта и инженерия", "ja": "プロダクトデザイン＆エンジニアリング"}',
  '{"en": ["Product strategy", "Web app", "Data pipeline"], "zh-cn": ["产品策略", "网站应用", "数据管道"], "zh-tw": ["產品策略", "網站應用", "資料管道"], "fr": ["Stratégie produit", "Application web", "Pipeline de données"], "de": ["Produktstrategie", "Web-App", "Datenpipeline"], "ru": ["Стратегия продукта", "Веб-приложение", "Дата-пайплайн"], "ja": ["プロダクト戦略", "Webアプリ", "データパイプライン"]}',
  '{"en": "Laurero helps Chinese students choose university applications with honest, data-backed guidance — full companionship through the whole decision.", "zh-cn": "Laurero 用诚实、有数据依据的指导帮中国学生做志愿选择——全程陪伴整个决策过程。", "zh-tw": "Laurero 用誠實、有資料依據的指導幫中國學生做志願選擇——全程陪伴整個決策過程。", "fr": "Laurero aide les étudiants chinois à choisir leurs candidatures universitaires avec des conseils honnêtes, fondés sur les données — un accompagnement complet.", "de": "Laurero hilft chinesischen Schülern bei der Uni-Bewerbung mit ehrlicher, datenbasierter Beratung — volle Begleitung durch die ganze Entscheidung.", "ru": "Laurero помогает китайским студентам выбирать вузы — честные рекомендации на основе данных и сопровождение на всём пути решения.", "ja": "Laurero は中国の学生の大学志願選択を支援——誠実でデータに裏打ちされた指導と、決定までのフル同伴。"}',
  '{"en": ["Credit-based freemium: 100 free credits, paid tiers up to lifetime", "Policy data refreshed weekly from official sources", "Built on honest advice, not inflated promises"], "zh-cn": ["积分制免费增值：100 免费积分，付费档至终身", "政策数据每周从官方来源更新", "立足诚实建议，不做夸大承诺"], "zh-tw": ["積分制免費增值：100 免費積分，付費檔至終身", "政策資料每週從官方來源更新", "立足誠實建議，不做誇大承諾"], "fr": ["Freemium à crédits : 100 crédits gratuits, offres payantes jusqu''au lifetime", "Données politiques actualisées chaque semaine depuis des sources officielles", "Des conseils honnêtes, pas des promesses gonflées"], "de": ["Freemium mit Credits: 100 Gratis-Credits, Paid-Stufen bis Lifetime", "Wöchentliche Policy-Updates aus offiziellen Quellen", "Ehrliche Beratung statt überzogener Versprechen"], "ru": ["Freemium на кредитах: 100 бесплатных кредитов, платные тарифы вплоть до lifetime", "Еженедельное обновление данных из официальных источников", "Честные советы вместо раздутых обещаний"], "ja": ["クレジット制フリーミアム：100無料クレジット、有料はライフタイムまで", "公式ソースから毎週更新される政策データ", "誠実な助言が基盤、誇大な約束はしない"]}',
  '{"en": "Laurero started from a simple frustration: application advice was either expensive, generic, or dishonest. The product combines official policy data, admission records, and score distributions into one conversational assistant.\n\nThe pricing is deliberately accessible — a small credit packs model with a generous free tier — so honest guidance isn''t a luxury good.", "zh-cn": "Laurero 源于一种简单的不满：志愿建议要么贵、要么泛、要么不诚实。它把官方政策数据、录取记录和分段表装进一个对话助手。\n\n定价刻意亲民——小额积分包加慷慨的免费档——让诚实的指导不是奢侈品。", "zh-tw": "Laurero 源於一種簡單的不滿：志願建議要麼貴、要麼泛、要麼不誠實。它把官方政策資料、錄取紀錄和分段表裝進一個對話助手。\n\n定價刻意親民——小額積分包加慷慨的免費檔——讓誠實的指導不是奢侈品。", "fr": "Laurero est né d''une frustration simple : les conseils d''orientation étaient chers, génériques ou malhonnêtes. Le produit combine données politiques officielles, dossiers d''admission et distributions de notes dans un assistant conversationnel.\n\nLe tarif est volontairement accessible — petits packs de crédits et offre gratuite généreuse — pour que l''honnêteté ne soit pas un luxe.", "de": "Laurero entstand aus simplem Frust: Bewerbungsberatung war teuer, generisch oder unehrlich. Das Produkt bündelt offizielle Policy-Daten, Zulassungsdaten und Notenverteilungen in einem conversational Assistant.\n\nDas Pricing ist bewusst zugänglich — kleine Credit-Pakete plus großzügige Free-Tier — damit ehrliche Beratung kein Luxus ist.", "ru": "Laurero родился из простого разочарования: консультации по поступлению были дорогими, шаблонными или нечестными. Продукт соединяет официальные данные, статистику приёма и распределения баллов в одном диалоговом ассистенте.\n\nЦены сознательно доступные — небольшие пакеты кредитов и щедрый бесплатный тариф, — чтобы честность не была роскошью.", "ja": "Laurero はシンプルな不満から生まれた：志願アドバイスは高額か、画一的か、不誠実だった。公式政策データ、合格実績、得点分布を一つの対話アシスタントに統合。\n\n料金は意図的に手頃に——少額クレジットと寛大な無料枠——誠実さが贅沢品にならないように。"}',
  '{"en": {"title": "Laurero", "description": "AI gaokao application advisor that dares to tell the truth."}, "zh-cn": {"title": "Laurero", "description": "敢说真话的 AI 高考志愿填报顾问。"}, "zh-tw": {"title": "Laurero", "description": "敢說真話的 AI 高考志願填報顧問。"}, "fr": {"title": "Laurero", "description": "Conseiller IA d''orientation gaokao qui ose dire la vérité."}, "de": {"title": "Laurero", "description": "KI-Berater für die Gaokao-Bewerbung, der die Wahrheit sagt."}, "ru": {"title": "Laurero", "description": "ИИ-консультант по gaokao, который не боится говорить правду."}, "ja": {"title": "Laurero", "description": "真実を語ることを恐れないAI高考志願アドバイザー。"}}'
);
